#!/usr/bin/env python3
"""Extract frontmatter and summaries from all SKILL.md files."""
import os
import sys
import yaml
import re
from pathlib import Path

SEARCH_DIRS = [
    "/home/toxic/.claude",
    "/home/toxic/.tau",
    "/home/toxic/.config/opencode",
    "/home/toxic/.config/claude",
    "/home/toxic/sovereign",
    "/home/toxic/.tau/agent/managed-skills",
]

def parse_frontmatter(content):
    """Parse YAML frontmatter from SKILL.md content."""
    if not content.startswith('---'):
        return None, content

    # Find the closing ---
    end = content.find('---', 3)
    if end == -1:
        return None, content

    yaml_text = content[3:end].strip()
    body = content[end+3:].strip()

    try:
        fm = yaml.safe_load(yaml_text)
    except yaml.YAMLError:
        fm = {}

    return fm, body

def extract_summary(body, description):
    """Generate a one-line summary from body or description."""
    # Try description first
    if description:
        desc = description.strip()
        if isinstance(desc, str):
            # Take first sentence or first line
            first_line = desc.split('\n')[0].strip()
            # Remove > prefix if present
            first_line = re.sub(r'^\s*>\s*', '', first_line)
            if len(first_line) > 200:
                first_line = first_line[:200] + '...'
            return first_line

    # Fall back to body
    if body:
        first_line = body.split('\n')[0].strip()
        # Remove markdown headers
        first_line = re.sub(r'^#+\s*', '', first_line)
        if len(first_line) > 200:
            first_line = first_line[:200] + '...'
        return first_line

    return ""

def extract_triggers(fm, description):
    """Extract trigger keywords from frontmatter or description."""
    # Check explicit fields
    for field in ['triggers', 'when-to-use', 'keywords', 'trigger']:
        if field in fm and fm[field]:
            val = fm[field]
            if isinstance(val, list):
                return ', '.join(val)
            return str(val)

    # Look for "Triggers on:" pattern in description
    if description:
        desc = str(description)
        match = re.search(r'Triggers?\s+(?:on:|upon:)?["\']?(.+?)["\']?', desc, re.IGNORECASE)
        if match:
            return match.group(1).strip()
        # Also look for "Triggered when" pattern
        match = re.search(r'Triggered\s+(?:when|by)\s+(?:the\s+user\s+)?["\']?(.+?)["\']?', desc, re.IGNORECASE)
        if match:
            return match.group(1).strip()

    return ""

def process_file(filepath):
    """Process a single SKILL.md file."""
    try:
        with open(filepath, 'r', encoding='utf-8', errors='replace') as f:
            content = f.read()
    except Exception as e:
        return None

    fm, body = parse_frontmatter(content)
    if fm is None:
        return None

    name = fm.get('name', '')
    description = fm.get('description', '')

    # Convert description to string if it's a multi-line YAML string
    if isinstance(description, str):
        description = description.strip()
    elif isinstance(description, list):
        description = ' '.join(description).strip()
    elif description is None:
        description = ""
    else:
        description = str(description)

    triggers = extract_triggers(fm, description)
    summary = extract_summary(body, description)

    # If no name but file exists, try to derive from path
    if not name:
        name = Path(filepath).parent.name

    return {
        'path': str(filepath),
        'name': name,
        'description': description[:500] if description else "",
        'triggers': triggers,
        'summary': summary[:500] if summary else "",
    }

def main():
    all_files = []
    for d in SEARCH_DIRS:
        if os.path.isdir(d):
            for root, dirs, files in os.walk(d):
                # Skip node_modules and other large dirs for speed
                dirs[:] = [d for d in dirs if d not in ('node_modules', '.git', '__pycache__', 'dist', 'build')]
                for f in files:
                    if f == 'SKILL.md':
                        all_files.append(os.path.join(root, f))

    all_files.sort()

    results = []
    for fp in all_files:
        result = process_file(fp)
        if result:
            results.append(result)

    # Write output
    output_path = "/home/toxic/.toolinv-skills.txt"
    with open(output_path, 'w', encoding='utf-8') as out:
        out.write(f"# SKILL.md Inventory\n")
        out.write(f"# Total files found: {len(results)}\n")
        out.write(f"# Generated: 2026-09-22\n")
        out.write(f"# Search directories: {', '.join(SEARCH_DIRS)}\n\n")

        for i, r in enumerate(results):
            out.write(f"## [{i+1}] {r['path']}\n")
            out.write(f"- **name**: {r['name']}\n")
            out.write(f"- **description**: {r['description']}\n")
            if r['triggers']:
                out.write(f"- **triggers**: {r['triggers']}\n")
            out.write(f"- **summary**: {r['summary']}\n")
            out.write(f"\n")

    print(f"Done. Processed {len(results)} SKILL.md files.")
    print(f"Output written to {output_path}")

    # Also print a quick stats summary
    with_frontmatter = sum(1 for r in results if r['name'])
    print(f"Files with frontmatter 'name' field: {with_frontmatter}")

if __name__ == '__main__':
    main()

